/** Represent an error thrown when sandbox runtime authentication refresh fails for a specific stage and name */
export class SandboxRuntimeAuthRefreshError extends Error {
  constructor(stage: SandboxExistingBoxStage, name: string, detail: string, cause?: unknown) {
    super(`${stage} sandbox auth refresh failed for ${name}: ${detail}`, { cause })
    this.name = 'SandboxRuntimeAuthRefreshError'
  }
}

/** Which step of the state-preserving stop→resume recovery failed. `stop` with a
 *  driver-unsupported cause means the platform cannot restart this box (the
 *  `tangle` driver exposes create/delete only); `probe` means the box restarted
 *  but is still unresponsive. */
export type SandboxRecoveryPhase = 'stop' | 'resume' | 'probe'

/**
 * Thrown when an unresponsive box could not be recovered by a state-preserving
 * restart. Contract: this error is only ever thrown with the workspace intact —
 * recovery never deletes. The caller decides what to do next (retry, surface to
 * the user, or explicitly replace via `forceNew`).
 */
export class SandboxRecoveryFailedError extends Error {
  readonly boxKey: string
  readonly stage: SandboxExistingBoxStage
  readonly phase: SandboxRecoveryPhase
  constructor(
    stage: SandboxExistingBoxStage,
    boxKey: string,
    phase: SandboxRecoveryPhase,
    detail: string,
    cause?: unknown,
  ) {
    super(
      `${stage} sandbox ${boxKey} failed liveness recovery at ${phase}: ${detail}. ` +
        `The workspace is preserved; pass forceNew to replace the box.`,
      { cause },
    )
    this.name = 'SandboxRecoveryFailedError'
    this.boxKey = boxKey
    this.stage = stage
    this.phase = phase
  }
}

// Materialize inline profile files into a running box via `box.exec`. Uses a
// base64 pipe so arbitrary content (scripts, unicode, special chars) lands
// byte-exact, and writes to ANY absolute path (e.g. /usr/local/bin) or a
// `~`-relative path — the exec runs as the sidecar, which is not bound by the
// safe-prefix allow-list the /files/write API enforces. Sets the executable
// bit when the mount declares it OR the target is a bin directory.
//
// Each file is written in several small execs (mkdir, one append per base64
// chunk, then a decode+cleanup) so no single exec request body trips the
// ~4 KiB proxy cap. Writes are sequential; a single bad mount stops the batch
// and the first failure is returned (fail-loud), the rest are not attempted.
//
// Each exec is bounded by a client-side hard timeout and retried with backoff
// on transient rate-limit/readiness/transport failures, so one wedged or early
// exec-plane request can never park the caller (and thus never park provisioning).
// A small pace between execs keeps the burst rate below the proxy throttle that
// triggers the hang.
/** Define options to control execution timeout, pacing, and retry behavior when writing profile files */
export interface WriteProfileFilesOptions {
  // Hard ceiling per exec (ms). A hung/wedged exec is abandoned and retried.
  execTimeoutMs?: number
  // Delay between execs (ms) to stay under the proxy throttle. 0 disables it.
  paceMs?: number
  // Max retries for a transient exec before failing loud.
  maxRetries?: number
}

// The workspace-relative target for a deferred inline mount when it can be
// materialized through the sidecar file API (`box.fs.writeMany` — FILES rate
// group, 300/min, whole-file, auto-mkdir) instead of the chunked terminal-exec
// path (50/min); null when it must stay on exec. The file API resolves relative
// paths from the workspace root, so eligibility is: inline and a path that
// resolves under the workspace root with no `..`/`.sidecar` segment. `~/…` and
// `/home/agent/…` are home-relative; agent sandboxes set $HOME to the workspace
// root, so both map to the same relative target. Other absolute (`/…`) and bare
// `~`/`~user` mounts stay on exec.
function fileApiTarget(mount: AgentProfileFileMount): string | null {
  if (mount.resource.kind !== 'inline') return null
  let rel: string
  if (mount.path.startsWith('~/')) rel = mount.path.slice(2)
  else if (mount.path.startsWith('/home/agent/')) rel = mount.path.slice('/home/agent/'.length)
  else if (mount.path.startsWith('/') || mount.path.startsWith('~')) return null
  else rel = mount.path
  if (rel.length === 0 || rel.startsWith('/') || rel.split('/').some((seg) => seg === '..' || seg === '.sidecar')) {
    return null
  }
  return rel
}

function isExecutableProfileFile(mount: AgentProfileFileMount): boolean {
  return mount.executable ?? PROFILE_BIN_DIR_RE.test(mount.path)
}

function profileFileMode(mount: AgentProfileFileMount): number | undefined {
  return isExecutableProfileFile(mount) ? 0o755 : undefined
}

function fileApiSupportsMode(box: SandboxInstance): boolean {
  const fs = box.fs as (SandboxInstance['fs'] & { supportsWriteMode?: boolean }) | undefined
  return fs?.supportsWriteMode === true
}

/** Write profile files to a sandbox with pacing, retries, and optional execution timeout handling */
export async function writeProfileFilesToBox(
  box: SandboxInstance,
  files: AgentProfileFileMount[],
  options: WriteProfileFilesOptions = {},
): Promise<Outcome<void>> {
  const execTimeoutMs = options.execTimeoutMs ?? PROFILE_WRITE_EXEC_TIMEOUT_MS
  const paceMs = options.paceMs ?? PROFILE_WRITE_PACE_MS
  const maxRetries = options.maxRetries ?? PROFILE_WRITE_MAX_RETRIES
  // The bulk of a profile corpus (skills, `~/.claude/skills/…`, config) is
  // inline and workspace-relative — write it in ONE paced,
  // retry-aware batch via the SDK's file API (`box.fs.writeMany`, FILES rate
  // group 300/min). The SDK owns the pacing + transient-retry this module used
  // to hand-roll. Absolute / bare-`~` paths can't use the file API
  // (prefix-restricted), so they stay on the chunked exec path.
  // Capability-guarded: SDKs without `writeMany` route everything through
  // exec; SDKs before @tangle-network/sandbox 0.9.4 keep executable files on
  // exec because they do not expose `supportsWriteMode` or forward file modes.
  const fileApiAvailable = typeof box.fs?.writeMany === 'function'
  const modeAwareFileApi = fileApiSupportsMode(box)
  const viaFileApi: { path: string; content: string; mode?: number }[] = []
  const viaExec: AgentProfileFileMount[] = []
  for (const mount of files) {
    if (mount.resource.kind !== 'inline') continue
    const fileApiPath = fileApiAvailable ? fileApiTarget(mount) : null
    const executable = isExecutableProfileFile(mount)
    if (fileApiPath !== null && (!executable || modeAwareFileApi)) {
      const mode = profileFileMode(mount)
      viaFileApi.push({
        path: fileApiPath,
        content: mount.resource.content ?? '',
        ...(mode !== undefined ? { mode } : {}),
      })
    }
    else viaExec.push(mount)
  }
  if (viaFileApi.length > 0) {
    // `writeMany` is fail-loud on the first file it can't write. Preserve the
    // cause so the runtime-auth-refresh wrapper still detects a 401 — it
    // recurses `.cause` for an AuthError/401 shape (see isRuntimeExecAuthError).
    try {
      await box.fs.writeMany(viaFileApi, { paceMs, maxRetries })
    } catch (err) {
      return fail(new Error('writeProfileFilesToBox: file-API batch write failed', { cause: err }))
    }
  }

  // Pace BETWEEN execs, not before the first or after the last. Shared across
  // the exec mounts so the (now smaller) executable/edge-case set stays paced.
  let execStarted = false

  // Pace + transient-retry ONE exec attempt: backoff/pace/fail-loud in one place.
  // `run` must be idempotent under unknown-outcome retries (exec writes
  // deterministic parts). A transient error retries with backoff up to
  // maxRetries (honoring a server Retry-After); anything else, or exhausting
  // retries, fails loud with the cause.
  const paceAndRetry = async <T>(run: () => Promise<T>, path: string): Promise<Outcome<T>> => {
    for (let attempt = 0; ; attempt++) {
      if (execStarted && paceMs > 0) await sleep(paceMs)
      execStarted = true
      try {
        return ok(await run())
      } catch (err) {
        const { retryable, retryAfterMs } = transientExecError(err)
        if (retryable && attempt < maxRetries) {
          const backoff = Math.min(PROFILE_WRITE_RETRY_BASE_MS * 2 ** attempt, PROFILE_WRITE_RETRY_MAX_MS)
          await sleep(retryAfterMs ?? backoff)
          continue
        }
        return fail(new Error(`writeProfileFilesToBox: exec failed for ${path}`, { cause: err }))
      }
    }
  }

  for (const mount of viaExec) {
    if (mount.resource.kind !== 'inline') continue // always true (viaExec is inline) — narrows for TS
    const content = mount.resource.content ?? ''
    const path = mount.path

    const b64 = Buffer.from(content, 'utf8').toString('base64')
    const b64Chunks: string[] = []
    for (let i = 0; i < b64.length; i += PROFILE_WRITE_B64_CHUNK_CHARS) {
      b64Chunks.push(b64.slice(i, i + PROFILE_WRITE_B64_CHUNK_CHARS))
    }
    const expectedSha256 = createHash('sha256').update(content, 'utf8').digest('hex')
    const dir = path.replace(/\/[^/]*$/, '')
    const executable = isExecutableProfileFile(mount)
    const q = shellPath(path)
    const qb64 = shellPath(`${path}.b64`)
    const qtmp = shellPath(`${path}.tmp`)
    const qpartPrefix = shellPath(`${path}.b64.part.`)

    // Run one exec step. Transport errors (incl. a wedged-proxy timeout) are
    // paced + retried by paceAndRetry; a non-zero exit is a REAL command failure
    // — surfaced immediately, never retried.
    const step = async (cmd: string): Promise<Outcome<void>> => {
      const res = await paceAndRetry(() => execWithTimeout(box, cmd, execTimeoutMs), path)
      if (!res.succeeded) return res
      const exec = res.value
      if (exec.exitCode !== 0) {
        return fail(
          new Error(
            `writeProfileFilesToBox: failed to write ${path} (exit ${exec.exitCode}): ${exec.stderr.slice(0, 500)}`,
          ),
        )
      }
      return ok(undefined)
    }

    // Ensure the target directory exists. Chunk/final commands below are
    // idempotent under unknown-outcome transport retries; this no-op/mkdir is too.
    const mkdir = dir && dir !== path ? `mkdir -p ${shellPath(dir)}` : ':'
    let res = await step(mkdir)
    if (!res.succeeded) return res

    // Write each deterministic part with overwrite, not append. If the server
    // writes a part but the HTTP response is lost, retrying the same step lands
    // the same bytes instead of duplicating them.
    for (let i = 0; i < b64Chunks.length; i++) {
      const slice = b64Chunks[i]!
      res = await step(`printf '%s' '${slice}' > ${shellPath(`${path}.b64.part.${i}`)}`)
      if (!res.succeeded) return res
    }

    // Materialize from deterministic parts into a temp file, verify its content
    // hash, then atomically move into place. If the final exec succeeds but its
    // response is lost, a retry first accepts an already-correct target and only
    // re-runs idempotent chmod/cleanup. Parts are cleaned only after the target
    // hash is known-good, so a retried final step can always reconstruct.
    const chmod = executable ? `chmod +x ${q} || exit 1; ` : ''
    const checksumMismatch = shellSingleQuote(`writeProfileFilesToBox: checksum mismatch for ${path}`)
    const finalCmd =
      `expected='${expectedSha256}'; ` +
      `if [ -f ${q} ] && [ "$(sha256sum ${q} | awk '{print $1}')" = "$expected" ]; then ` +
      `${chmod}rm -f ${qb64} ${qtmp}; i=0; while [ "$i" -lt ${b64Chunks.length} ]; do rm -f ${qpartPrefix}$i; i=$((i+1)); done; exit 0; fi; ` +
      `: > ${qb64} && ` +
      `i=0; while [ "$i" -lt ${b64Chunks.length} ]; do cat ${qpartPrefix}$i >> ${qb64} || exit 1; i=$((i+1)); done && ` +
      `base64 -d < ${qb64} > ${qtmp} && ` +
      `[ "$(sha256sum ${qtmp} | awk '{print $1}')" = "$expected" ] || { echo ${checksumMismatch} >&2; exit 1; }; ` +
      `mv ${qtmp} ${q} && ` +
      `${executable ? `chmod +x ${q} && ` : ''}` +
      `[ "$(sha256sum ${q} | awk '{print $1}')" = "$expected" ] || { echo ${checksumMismatch} >&2; exit 1; }; ` +
      `rm -f ${qb64} ${qtmp}; i=0; while [ "$i" -lt ${b64Chunks.length} ]; do rm -f ${qpartPrefix}$i; i=$((i+1)); done`
    res = await step(finalCmd)
    if (!res.succeeded) return res
  }
  return ok(undefined)
}

// Resolve the shell's deferred (inline) profile files and write them into a
// box that already exists (reuse/resume paths). No-op unless the shell opts
// into deferProfileFiles. Idempotent overwrite — a redeploy with new skills
// refreshes the corpus on the next ensure call.
// Box-metadata key holding the content hash of the deferred corpus that was
// written to the box at CREATE. On reuse, an unchanged hash means the skills are
// already on disk, so the (large, file-API) re-write can be skipped.
const DEFERRED_CORPUS_HASH_KEY = 'agentAppDeferredCorpusHash'

/** Stable content hash of the deferred file corpus (path + inline content).
 *  Unchanged corpus ⇒ same hash; a new/edited/removed skill ⇒ different hash.
 *  Exported for the reuse-skip test. */
export function deferredCorpusHash(files: AgentProfileFileMount[]): string {
  const norm = files
    .map((f) => ({
      p: f.path,
      c: f.resource.kind === 'inline' ? ((f.resource as { content?: string }).content ?? '') : `ref:${f.resource.kind}`,
    }))
    .sort((a, b) => (a.p < b.p ? -1 : a.p > b.p ? 1 : 0))
  return createHash('sha256').update(JSON.stringify(norm), 'utf8').digest('hex')
}

async function materializeDeferredFilesForExistingBox(
  shell: SandboxRuntimeConfig,
  client: Sandbox,
  box: SandboxInstance,
  stage: SandboxExistingBoxStage,
  name: string,
  workspaceId: string,
  userId: string | undefined,
  harness: Harness,
): Promise<Outcome<SandboxInstance>> {
  if (!shell.deferProfileFiles) return ok(box)
  const connectedIntegrationIds = await shell.connectedIntegrationIds(workspaceId)
  const buildCtx: SandboxBuildContext = {
    workspaceId,
    connectedIntegrationIds,
    ...(userId ? { userId } : {}),
  }
  const files = await shell.files(buildCtx)
  const fullProfile = shell.profile({ extraFiles: files, harness })
  const { deferredFiles } = splitDeferredProfileFiles(fullProfile)
  if (deferredFiles.length === 0) return ok(box)
  // Skip the whole re-write when the corpus is UNCHANGED since the box was
  // created with it. The skill corpus is large and the bulk goes through the
  // file API (writeMany) UNCONDITIONALLY, so re-writing it on every reuse adds
  // seconds of latency to each turn. The create payload stamps the corpus hash
  // into box metadata; a matching hash means the skills are already on disk.
  // Fail-safe: a missing or mismatched hash (e.g. a redeploy with new skills, or
  // a box created before this optimization) WRITES — a stale skip is never
  // risked. Reads metadata only, so no extra exec/round-trip.
  const stampedHash = (box.metadata as Record<string, unknown> | undefined)?.[DEFERRED_CORPUS_HASH_KEY]
  if (typeof stampedHash === 'string' && stampedHash === deferredCorpusHash(deferredFiles)) return ok(box)
  return writeDeferredFilesWithRuntimeAuthRefresh(client, box, deferredFiles, stage, name)
}

async function listRunning(
  client: Sandbox,
  name: string,
): Promise<Outcome<SandboxInstance | null>> {
  try {
    const running = await client.list({ status: 'running' })
    return ok(running.find((s) => s.name === name) ?? null)
  } catch (err) {
    return fail(err)
  }
}

async function listStopped(
  client: Sandbox,
  name: string,
): Promise<Outcome<SandboxInstance | null>> {
  try {
    const stopped = await client.list({ status: 'stopped' })
    return ok(stopped.find((s) => s.name === name) ?? null)
  } catch (err) {
    return fail(err)
  }
}

async function deleteBox(box: SandboxInstance): Promise<Outcome<void>> {
  try {
    const acknowledgement = await box.delete({ until: 'removed' })
    livenessVerifiedAt.delete(box.id)
    // Creation reuses this box's name as its idempotency key.
    if (acknowledgement.removal === 'pending') {
      return fail(new Error(`sandbox ${box.id} removal is still pending; retry replacement after removal completes`))
    }
    return ok(undefined)
  } catch (err) {
    return fail(err)
  }
}

// The SDK narrows `backend.type` to its own BackendType union and
// `initialUsers[].role` to PermissionLevel — neither symbol is exported. The
// create payload is assembled with the product's Harness/role strings, which
// are a superset surface; the localized cast at the boundary is the only place
// this widening is allowed, and the runtime contract (the sidecar boots the
// named harness) is what enforces correctness.
type CreatePayload = Parameters<Sandbox['create']>[0]

// ---------------------------------------------------------------------------
// Provision-time S-cost gates. Both run immediately before `client.create` —
// each catches an input class that can NEVER produce a working sandbox, so
// failing at POST-time with actionable detail beats a platform 4xx (or a box
// that boots and then E2BIGs on every exec).

/** Appended to a prompt-budget throw from any of this module's three choke
 *  points. A product that already raised the cap at compose time
 *  (`composeAgentProfile(base, channels, overlay, { maxSystemPromptBytes })` —
 *  gtm-agent uses 50_000) has to declare the SAME decision on the shell, or the
 *  shell's default reads as a contradiction instead of a missing declaration. */
const SHELL_PROMPT_BUDGET_HINT =
  'If this prompt size is a decision you already made at compose time, mirror it on the shell as ' +
  '`promptBudget: { maxSystemPromptBytes, overBudgetReason }` — the shell gate is the one that sees the profile actually sent.'

/** Gate on the provision body: the platform orchestrator caps the create
 *  payload at 256 KiB; 240 KB leaves headroom for transport framing. An
 *  over-cap payload fails provisioning 100% of the time (a 282 KB payload
 *  shipped once and no sandbox could ever be created). */
export const PROVISION_PAYLOAD_MAX_BYTES = 240_000

/** Per-variable env gate: the kernel rejects any single `NAME=value` env entry
 *  over MAX_ARG_STRLEN (131072 bytes) with E2BIG, killing every exec inside
 *  the box. 120 KB leaves headroom for the name and framing. */
export const ENV_VALUE_MAX_BYTES = 120_000

/** Default wait for a box to reach `running`. Overridable per shell via
 *  {@link SandboxRuntimeConfig.provisionTimeoutMs}. */
export const DEFAULT_PROVISION_TIMEOUT_MS = 120_000

/** Total env gate: the whole environment block shares the payload budget with
 *  the profile; past 200 KB the provision body cannot stay under the cap. */
export const ENV_TOTAL_MAX_BYTES = 200_000

function utf8ByteLength(value: unknown): number {
  return new TextEncoder().encode(typeof value === 'string' ? value : JSON.stringify(value ?? null))
    .byteLength
}

/** Structural slice of the profile the payload gate reads: it only measures
 *  the profile's serialized size and names `resources.files` in the breakdown,
 *  so callers composing a payload outside the SDK (products, tests) can pass a
 *  plain object without casting through `AgentProfile`. */
export interface ProvisionProfileSection {
  resources?: { files?: readonly unknown[] }
}

/** The provision-payload sections the size gates need to see. Structural so
 *  the gate is testable without the SDK's (unexported) create-payload type. */
export interface ProvisionPayloadSections {
  env?: Record<string, string>
  secrets?: readonly string[] | 'all'
  /** `profile` may also be a named-profile string ref (the SDK's
   *  `BackendConfig` union) — a string ref is tiny and has no files channel. */
  backend?: { profile?: string | ProvisionProfileSection }
}

/**
 * Throw when the serialized provision payload exceeds
 * {@link PROVISION_PAYLOAD_MAX_BYTES}. The error carries a per-section byte
 * breakdown (profile/files/env/secrets) so the offending channel is named, not
 * guessed.
 */
export function assertProvisionPayloadWithinCap(payload: ProvisionPayloadSections): void {
  const total = utf8ByteLength(payload)
  if (total <= PROVISION_PAYLOAD_MAX_BYTES) return
  const profile = payload.backend?.profile
  const files = (typeof profile === 'string' ? undefined : profile?.resources?.files) ?? []
  const breakdown =
    `profile=${utf8ByteLength(profile ?? null)}B ` +
    `(files=${utf8ByteLength(files)}B), ` +
    `env=${utf8ByteLength(payload.env ?? {})}B, ` +
    `secrets=${utf8ByteLength(payload.secrets ?? [])}B`
  throw new Error(
    `sandbox provision payload is ${total} bytes — over the ${PROVISION_PAYLOAD_MAX_BYTES}-byte gate ` +
      `(the platform caps the create body at 256 KiB; an over-cap payload can never create a sandbox). ` +
      `Breakdown: ${breakdown}. ` +
      `Hint: set deferProfileFiles: true or move content to resources.`,
  )
}

/**
 * Throw when any single env value exceeds {@link ENV_VALUE_MAX_BYTES} or the
 * whole env block exceeds {@link ENV_TOTAL_MAX_BYTES}, naming the offending
 * variable. This is the E2BIG incident class: the box may even provision, but
 * every exec inside it dies on the oversized entry.
 */
export function assertEnvWithinLimits(env: Record<string, string>): void {
  let total = 0
  let largest: { name: string; bytes: number } | null = null
  for (const [name, value] of Object.entries(env)) {
    const bytes = utf8ByteLength(`${name}=${value}`)
    total += bytes
    if (!largest || bytes > largest.bytes) largest = { name, bytes }
    if (bytes > ENV_VALUE_MAX_BYTES) {
      throw new Error(
        `sandbox env var ${name} is ${bytes} bytes — over the ${ENV_VALUE_MAX_BYTES}-byte gate ` +
          `(kernel MAX_ARG_STRLEN is 131072 bytes per env entry; anything larger E2BIGs every exec). ` +
          `Write large content to a file mount or resource instead of an env var.`,
      )
    }
  }
  if (total > ENV_TOTAL_MAX_BYTES) {
    const worst = largest ? ` Largest: ${largest.name} (${largest.bytes}B).` : ''
    throw new Error(
      `sandbox env block is ${total} bytes total — over the ${ENV_TOTAL_MAX_BYTES}-byte gate.${worst} ` +
        `Write large content to a file mount or resource instead of env vars.`,
    )
  }
}

// The SDK owns the exec deadline. Await settlement before starting recovery;
// an application timeout race would leave the original request in flight.
async function isBoxAlive(
  box: SandboxInstance,
  probe: LivenessProbeConfig | undefined,
): Promise<Outcome<void>> {
  if (!probe) return ok(undefined)
  try {
    const alive = await box.exec('echo alive', { timeoutMs: probe.execTimeoutMs ?? 5000 })
    if (alive.exitCode !== 0 || alive.stdout.trim() !== 'alive') {
      return fail(new Error('alive check did not return a successful alive marker'))
    }
    return ok(undefined)
  } catch (cause) {
    return fail(new Error('alive check failed', { cause }))
  }
}

const DEFAULT_LIVENESS_CACHE_TTL_MS = 5_000

function hasRecentLivenessVerification(
  box: SandboxInstance,
  probe: LivenessProbeConfig,
  now = Date.now(),
): boolean {
  const ttlMs = probe.cacheTtlMs ?? DEFAULT_LIVENESS_CACHE_TTL_MS
  if (!Number.isFinite(ttlMs) || ttlMs <= 0) return false
  const verifiedAt = livenessVerifiedAt.get(box.id)
  if (verifiedAt !== undefined && now - verifiedAt < ttlMs) return true
  livenessVerifiedAt.delete(box.id)
  return false
}

const RUNTIME_CONNECTION_WAIT_MS = 30_000
const RUNTIME_CONNECTION_POLL_MS = 1_000

// `sidecarUrl` is a product/forward-compat field the orchestrator may set on
// the connection ahead of the SDK declaring it — the v0.6 `SandboxConnection`
// exposes only `runtimeUrl`. Read it through a typed augmentation rather than an
// ad-hoc cast (a plain `SandboxConnection` satisfies the optional field), and
// fall back to the SDK runtime URL. The product-facing `WorkspaceSandboxInstanceLike`
// carries the same field for consumers driving their own box types.
type RuntimeConnectionFields = SandboxConnection & {
  sidecarUrl?: string
  authToken?: string
  sidecarToken?: string
  authTokenExpiresAt?: string | number | Date
  sidecarTokenExpiresAt?: string | number | Date
}

function sandboxRuntimeUrl(box: SandboxInstance): string | undefined {
  const connection: RuntimeConnectionFields | undefined = box.connection
  return connection?.sidecarUrl ?? connection?.runtimeUrl
}

function runtimeAuthExpiresAtMs(value: string | number | Date | undefined): number | undefined {
  if (value instanceof Date) return value.getTime()
  if (typeof value === 'number') return value
  if (typeof value !== 'string' || value.trim() === '') return undefined
  const parsed = Date.parse(value)
  return Number.isNaN(parsed) ? undefined : parsed
}

function hasFreshRuntimeExecAuth(box: SandboxInstance, now = Date.now()): boolean {
  const connection: RuntimeConnectionFields | undefined = box.connection
  const token = connection?.authToken ?? connection?.sidecarToken
  if (!sandboxRuntimeUrl(box) || !token) return false
  const expiresAt = runtimeAuthExpiresAtMs(
    connection?.authTokenExpiresAt ?? connection?.sidecarTokenExpiresAt,
  )
  return expiresAt === undefined || expiresAt > now + RUNTIME_AUTH_REFRESH_SKEW_MS
}

function sandboxEdgeFailed(box: SandboxInstance): boolean {
  // `edgeStatus`/`edgeError` are declared on the SDK's `SandboxConnection`, so no cast.
  const connection = box.connection
  return connection?.edgeStatus === 'failed' || Boolean(connection?.edgeError)
}

async function refreshRuntimeConnection(
  client: Sandbox,
  box: SandboxInstance,
): Promise<SandboxInstance> {
  let current = box
  if (sandboxRuntimeUrl(current)) return current

  const deadline = Date.now() + RUNTIME_CONNECTION_WAIT_MS
  while (Date.now() < deadline) {
    // Tolerate transient refresh/get failures (5xx, network blips) while the
    // orchestrator is still attaching the connection: swallow and retry. A box
    // that never surfaces a runtime URL is returned as-is so the caller's
    // readiness gate (isReusableBox) sends it into state-preserving recovery
    // (or fails loud) — rather than this poll throwing a hard provisioning
    // failure on a recoverable hiccup.
    try {
      await current.refresh()
      if (sandboxRuntimeUrl(current)) return current

      const latest = await client.get(current.id)
      if (latest) current = latest
      if (sandboxRuntimeUrl(current)) return current
    } catch {
      // transient — fall through to the poll delay and retry
    }

    await new Promise((resolve) => setTimeout(resolve, RUNTIME_CONNECTION_POLL_MS))
  }

  return current
}

async function bestEffortRefreshRuntimeExecAuth(
  client: Sandbox,
  box: SandboxInstance,
  stage: SandboxExistingBoxStage,
  name: string,
): Promise<Outcome<SandboxInstance>> {
  let current = box

  try {
    await current.refresh()
    if (hasFreshRuntimeExecAuth(current)) return ok(current)
  } catch (err) {
    if (isRuntimeAuthRefreshDenied(err)) {
      return fail(
        new SandboxRuntimeAuthRefreshError(
          stage,
          name,
          'runtime exec auth refresh was unauthorized',
          err,
        ),
      )
    }
  }

  try {
    const latest = await client.get(current.id)
    if (latest) current = latest
    if (hasFreshRuntimeExecAuth(current)) return ok(current)
  } catch (err) {
    if (isRuntimeAuthRefreshDenied(err)) {
      return fail(
        new SandboxRuntimeAuthRefreshError(
          stage,
          name,
          'runtime exec auth re-fetch was unauthorized',
          err,
        ),
      )
    }
  }

  return ok(current)
}

async function refreshRuntimeExecAuth(
  client: Sandbox,
  box: SandboxInstance,
  stage: SandboxExistingBoxStage,
  name: string,
): Promise<Outcome<SandboxInstance>> {
  let current = box
  let lastError: unknown
  const deadline = Date.now() + RUNTIME_CONNECTION_WAIT_MS

  while (Date.now() < deadline) {
    try {
      await current.refresh()
      if (hasFreshRuntimeExecAuth(current)) return ok(current)

      const latest = await client.get(current.id)
      if (latest) current = latest
      if (hasFreshRuntimeExecAuth(current)) return ok(current)
    } catch (err) {
      lastError = err
    }

    await new Promise((resolve) => setTimeout(resolve, RUNTIME_CONNECTION_POLL_MS))
  }

  const detail = sandboxRuntimeUrl(current)
    ? 'runtime exec credentials are missing or expired after refresh'
    : 'runtime connection is missing after refresh'
  return fail(new SandboxRuntimeAuthRefreshError(stage, name, detail, lastError))
}

async function writeDeferredFilesWithRuntimeAuthRefresh(
  client: Sandbox,
  box: SandboxInstance,
  files: AgentProfileFileMount[],
  stage: SandboxExistingBoxStage,
  name: string,
): Promise<Outcome<SandboxInstance>> {
  let writeBox = box

  if (!hasFreshRuntimeExecAuth(writeBox)) {
    const refreshed = await bestEffortRefreshRuntimeExecAuth(client, writeBox, stage, name)
    if (!refreshed.succeeded) return fail(refreshed.error)
    writeBox = refreshed.value
  }

  const first = await writeProfileFilesToBox(writeBox, files)
  if (first.succeeded) return ok(writeBox)
  if (!isRuntimeExecAuthError(first.error)) return fail(first.error)

  const refreshed = await refreshRuntimeExecAuth(client, writeBox, stage, name)
  if (!refreshed.succeeded) return fail(refreshed.error)

  const second = await writeProfileFilesToBox(refreshed.value, files)
  if (second.succeeded) return ok(refreshed.value)
  if (!isRuntimeExecAuthError(second.error)) return fail(second.error)

  return fail(
    new SandboxRuntimeAuthRefreshError(
      stage,
      name,
      'runtime exec remained unauthorized after auth refresh',
      second.error,
    ),
  )
}

// Decide whether an existing (reused or resumed) box is safe to hand back.
// `refreshRuntimeConnection` has already polled for the runtime URL, so a box
// that still has none never became connectable and must not be silently
// reused — downstream exec/terminal traffic would fail against it. A failed
// edge is likewise unusable. Only when the connection is present do we spend
// an exec round-trip on the liveness probe. A box that fails this gate is
// RECOVERED (stop→resume, workspace intact) or fails loud — never deleted.
async function isReusableBox(
  box: SandboxInstance,
  probe: LivenessProbeConfig | undefined,
): Promise<Outcome<void>> {
  if (sandboxEdgeFailed(box) || !sandboxRuntimeUrl(box)) {
    livenessVerifiedAt.delete(box.id)
    return fail(new Error(sandboxEdgeFailed(box) ? 'runtime edge readiness failed' : 'runtime URL is missing'))
  }
  if (!probe) return ok(undefined)
  if (hasRecentLivenessVerification(box, probe)) return ok(undefined)
  const alive = await isBoxAlive(box, probe)
  if (alive.succeeded) livenessVerifiedAt.set(box.id, Date.now())
  else livenessVerifiedAt.delete(box.id)
  return alive
}

// Resume a stopped box and wait for it to reach running.
function stoppedBoxResumeError(box: SandboxInstance, cause: unknown): unknown {
  const error = cause instanceof Error ? cause : new Error(String(cause))
  const code = (error as { code?: unknown }).code
  if (code === SANDBOX_BACKING_CONTAINER_MISSING_CODE) return cause
  if (code !== undefined && code !== 'SERVER_ERROR') return cause
  if (!isLegacySandboxBackingContainerMissingMessage(error.message)) return cause

  const status = typeof cause === 'object' && cause !== null
    ? (cause as { status?: unknown }).status
    : undefined
  if (typeof status !== 'number' && typeof status !== 'string') return cause
  const wrapped = new Error(error.message, { cause: error })
  wrapped.name = error.name

  return Object.assign(wrapped, {
    status,
    origin: 'sandbox-api',
    endpoint: `/v1/sandboxes/${encodeURIComponent(box.id)}/resume`,
    ...(typeof code === 'number' || typeof code === 'string' ? { code } : {}),
  })
}

async function resumeStoppedBox(
  box: SandboxInstance,
  timeoutMs: number,
  onProgress?: (event: ProvisionEvent) => void,
): Promise<Outcome<SandboxInstance>> {
  try {
    livenessVerifiedAt.delete(box.id)
    await box.resume({ timeoutMs })
    await box.waitFor('running', { timeoutMs, ...(onProgress ? { onProgress } : {}) })
    return ok(box)
  } catch (cause) {
    return fail(stoppedBoxResumeError(box, cause))
  }
}

// State-preserving recovery for a box that failed the reuse gate: stop (keeps
// the workspace — the platform's suspend path never scrubs storage), resume,
// then re-probe. `box.delete()` is DEPROVISIONING — it wipes the persistent
// workspace (sessions, uncommitted files, everything outside the product's own
// DB) — so it must never be a recovery action (#299: a single slow exec or a
// crashed harness process used to destroy a user's workspace). This restarts
// the container, which also reboots a dead sidecar/harness process. Every
// failure throws SandboxRecoveryFailedError with the workspace intact —
// including on the `tangle` driver, where stop is unsupported and the throw
// carries the platform's rejection as its cause.
async function recoverUnresponsiveBox(
  client: Sandbox,
  box: SandboxInstance,
  probe: LivenessProbeConfig | undefined,
  stage: SandboxExistingBoxStage,
  name: string,
  resumeTimeout: number,
  onProgress?: (event: ProvisionEvent) => void,
): Promise<SandboxInstance> {
  try {
    await box.stop()
  } catch (err) {
    throw new SandboxRecoveryFailedError(
      stage,
      name,
      'stop',
      'the platform could not stop the box for a state-preserving restart',
      err,
    )
  }
  const resumed = await resumeStoppedBox(box, resumeTimeout, onProgress)
  if (!resumed.succeeded) {
    throw new SandboxRecoveryFailedError(
      stage,
      name,
      'resume',
      'the box did not reach running after a state-preserving restart',
      resumed.error,
    )
  }
  const recovered = await refreshRuntimeConnection(client, resumed.value)
  const reusable = await isReusableBox(recovered, probe)
  if (!reusable.succeeded) {
    throw new SandboxRecoveryFailedError(
      stage,
      name,
      'probe',
      `the box is still unresponsive after a state-preserving restart: ${reusable.error.message}`,
      reusable.error,
    )
  }
  return recovered
}

/** Scope + the client and box key every workspace-scoped sandbox call needs.
 *  One place resolves credentials and derives the box name, so the ensure and
 *  peek paths cannot drift on which key a workspace's box lives under. */
async function resolveWorkspaceSandboxClient(
  shell: SandboxRuntimeConfig,
  workspaceId: string,
  userId: string | undefined,
): Promise<{ scope: SandboxScope; client: Sandbox; name: string }> {
  const scope: SandboxScope = { workspaceId, ...(userId ? { userId } : {}) }
  const creds = await shell.credentials(scope)
  if (!creds) throw new Error('sandbox credentials are required (apiKey/baseUrl)')
  return {
    scope,
    client: getClientFromCreds(creds),
    name: shell.boxKey ? shell.boxKey(scope) : shell.name(workspaceId),
  }
}

/** What a peek can find. `warming` means the control plane is running while
 *  the filesystem incarnation is still transitioning. `not-running` carries
 *  the platform's own state string (`stopped`, `starting`, `failed`, …) —
 *  narrowing it to a union here would drop states the platform adds later,
 *  and every caller wants it for a log. */
export type PeekWorkspaceSandboxOutcome =
  | { status: 'running'; box: SandboxInstance }
  | { status: 'warming'; readiness: 'transitioning'; box: SandboxInstance }
  | { status: 'not-running'; state: string; box: SandboxInstance }
  | { status: 'absent' }

/**
 * Read-only twin of {@link ensureWorkspaceSandbox}: report whether a
 * workspace's box exists and is fully ready, WITHOUT provisioning, resuming,
 * or bootstrapping anything.
 *
 * This is what a read-mostly path needs — a file-index route's `authorize`
 * seam, a stale-lock reconciliation, a status badge. Calling `ensure` from one
 * of those spins a box up as a side effect of a read (legal-agent #509), and
 * costs the caller a cold start it never asked for.
 *
 * Matching is on BOTH the box key and the display name, IN THAT ORDER.
 * `client.get(id)` keys on the platform's opaque sandbox id, not the
 * deterministic key a product derives from a workspace, and is itself a
 * `list().find` underneath — so a lookup by identity has to list and match.
 * Provisioning here always stamps `name` with the box key, so the key is the
 * authoritative match; the display-name pass exists only to adopt boxes on a
 * host that predates that convention. The order matters: a single unordered
 * `find` returns whichever the platform happens to list first, so a stopped
 * display-name box could shadow a running box-key one and report
 * `not-running` for a live workspace.
 *
 * Unlike `ensure`, this lists ALL statuses in one call: distinguishing "no box"
 * from "box is stopped" is the whole point, and a status-filtered list cannot.
 *
 * A `client.list()` rejection propagates RAW, unlike the `Outcome`-wrapping
 * helpers `ensure` uses internally. That is deliberate: there is no honest
 * outcome to map a listing failure onto — it is not `absent` and not
 * `not-running`, and inventing one would have callers act on a status the
 * platform never reported. Callers that must tolerate it say so explicitly
 * (the stale-turn-lock policy documents "a throw is treated as unreachable").
 */
export async function peekWorkspaceSandbox(
  shell: SandboxRuntimeConfig,
  options: { workspaceId: string; userId?: string },
): Promise<PeekWorkspaceSandboxOutcome> {
  const { client, name } = await resolveWorkspaceSandboxClient(shell, options.workspaceId, options.userId)
  const displayName = shell.name(options.workspaceId)
  const boxes = await client.list()
  const match = boxes.find((box) => box.name === name) ?? boxes.find((box) => box.name === displayName)
  if (!match) return { status: 'absent' }
  if (match.status !== 'running') return { status: 'not-running', state: match.status, box: match }
  if (match.filesystemIncarnationReadiness === 'transitioning') {
    return { status: 'warming', readiness: 'transitioning', box: match }
  }
  if (match.filesystemIncarnationReadiness !== 'ready') {
    throw new Error(`sandbox ${match.id} is running without filesystem incarnation readiness`)
  }
  return { status: 'running', box: match }
}

async function resolveWorkspaceRuntimeEnv(
  shell: SandboxRuntimeConfig,
  scope: SandboxScope,
): Promise<Record<string, string>> {
  const env = await shell.runtimeEnv?.(scope) ?? {}
  assertEnvWithinLimits(env)
  return env
}

// All retained-box paths renew credentials before the product bootstrap.
async function finalizeExistingBox(
  shell: SandboxRuntimeConfig,
  client: Sandbox,
  box: SandboxInstance,
  stage: SandboxExistingBoxStage,
  name: string,
  workspaceId: string,
  userId: string | undefined,
  harness: Harness,
  scope: SandboxScope,
): Promise<SandboxInstance> {
  await assertExistingBoxEgress(box, shell.egressPolicy, shell.migrateEgressPolicy, stage, name)
  const written = await materializeDeferredFilesForExistingBox(
    shell,
    client,
    box,
    stage,
    name,
    workspaceId,
    userId,
    harness,
  )
  if (!written.succeeded) {
    throw deferredProfileWriteFailed(stage, name, written.error)
  }
  const finalBox = written.value
  const runtimeEnv = await resolveWorkspaceRuntimeEnv(shell, scope)
  if (Object.keys(runtimeEnv).length > 0) {
    await finalBox.setRuntimeEnv(runtimeEnv)
  }
  if (shell.bootstrap) {
    const boot = await shell.bootstrap(finalBox, scope)
    if (!boot.succeeded) {
      throw new Error(`bootstrap failed on ${stage} box ${name}`, { cause: boot.error })
    }
  }
  return finalBox
}

function canonicalizeJson(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonicalizeJson)
  if (value === null || typeof value !== 'object') return value
  return Object.fromEntries(
    Object.entries(value as Record<string, unknown>)
      .sort(([left], [right]) => left < right ? -1 : left > right ? 1 : 0)
      .map(([key, entry]) => [key, canonicalizeJson(entry)]),
  )
}

function normalizedEgressPolicy(policy: EgressPolicy): string {
  const normalized: Record<string, unknown> = { ...policy }
  if (policy.mode === 'strict') {
    normalized.allowDomains = [...new Set(
      (policy.allowDomains ?? [])
        .map((domain) => domain.trim().toLowerCase())
        .filter(Boolean),
    )].sort()
    normalized.includeImplicitDomains = policy.includeImplicitDomains !== false
  } else {
    // `allowDomains` and `includeImplicitDomains` are ignored in open and
    // blocked modes, and the platform keeps a box's old strict list attached
    // after a migration to open. Comparing them refused a box that already had
    // exactly the policy asked for, and every reuse of that box after.
    delete normalized.allowDomains
    delete normalized.includeImplicitDomains
  }
  return JSON.stringify(canonicalizeJson(normalized))
}

function existingBoxEgressError(
  operation: 'read' | 'migration',
  box: SandboxInstance,
  stage: SandboxExistingBoxStage,
  name: string,
  cause: unknown,
): Error {
  const error = cause instanceof Error ? cause : new Error(String(cause))
  const status = (error as { status?: unknown }).status
  const suffix = operation === 'migration' ? '/egress' : ''
  return Object.assign(
    new Error(`egress policy ${operation} failed on ${stage} box ${name}: ${error.message}`, {
      cause: error,
    }),
    {
      origin: 'sandbox-api',
      endpoint: `/v1/sandboxes/${encodeURIComponent(box.id)}${suffix}`,
      ...(typeof status === 'number' || typeof status === 'string' ? { status } : {}),
    },
  )
}

async function assertExistingBoxEgress(
  box: SandboxInstance,
  desired: EgressPolicy | undefined,
  migrate: boolean | undefined,
  stage: SandboxExistingBoxStage,
  name: string,
): Promise<void> {
  if (!desired) return
  let current: Awaited<ReturnType<SandboxInstance['egress']['get']>>
  try {
    current = await box.egress.get()
  } catch (cause) {
    throw existingBoxEgressError('read', box, stage, name, cause)
  }
  const matchingPolicy = normalizedEgressPolicy(current.policy) === normalizedEgressPolicy(desired)
  const explicitSource = current.source !== 'platform'
  if (matchingPolicy && explicitSource) return

  if (migrate) {
    try {
      await box.egress.update(desired)
      const migrated = await box.egress.get()
      const migratedPolicy = normalizedEgressPolicy(migrated.policy) === normalizedEgressPolicy(desired)
      if (migratedPolicy && migrated.source !== 'platform') return
      current = migrated
    } catch (cause) {
      throw existingBoxEgressError('migration', box, stage, name, cause)
    }
  }

  throw new SandboxEgressPolicyMismatchError(
    stage,
    name,
    current.policy,
    current.source,
    desired,
  )
}

/** Reuse a workspace sandbox, or remove its previous runtime before provisioning a replacement. */
export async function ensureWorkspaceSandbox(
  shell: SandboxRuntimeConfig,
  options: EnsureWorkspaceSandboxOptions,
): Promise<SandboxInstance> {
  // A budget refusal must land before any box exists, so it runs ahead of both
  // the first attempt and the unbringable-box replacement below.
  await options.spend?.beforeProvision?.({
    workspaceId: options.workspaceId,
    ...(options.userId ? { userId: options.userId } : {}),
  })
  const box = await bringUpWorkspaceSandbox(shell, options)
  await observeProvisionedBox(shell, options, box)
  return box
}

/**
 * Report a now-billable box to the spend seam.
 *
 * Awaited rather than fired and forgotten: an expectation ledger with holes
 * reports boxes it simply failed to record as `unknown-box`, and an alert that
 * cries wolf is worse than no alert. The cost is one local write on a path that
 * already makes at least one platform round trip, so it is not the term that
 * decides provisioning latency.
 *
 * Errors are swallowed — the box is up, and failing the caller because
 * bookkeeping failed would trade a real capability for a record of it.
 */
async function observeProvisionedBox(
  shell: SandboxRuntimeConfig,
  options: EnsureWorkspaceSandboxOptions,
  box: SandboxInstance,
): Promise<void> {
  if (!options.spend?.onProvisioned) return
  const resources = shell.resources ?? DEFAULT_SANDBOX_RESOURCES
  try {
    await options.spend.onProvisioned({
      workspaceId: options.workspaceId,
      ...(options.userId ? { userId: options.userId } : {}),
      sandboxId: box.id,
      boxKey: box.name,
      idleTimeoutSeconds: resources.idleTimeoutSeconds,
      maxLifetimeSeconds: resources.maxLifetimeSeconds,
      at: Date.now(),
    })
  } catch {
    // An observability seam must never take down the provision it reports on.
  }
}

async function bringUpWorkspaceSandbox(
  shell: SandboxRuntimeConfig,
  options: EnsureWorkspaceSandboxOptions,
): Promise<SandboxInstance> {
  try {
    return await provisionWorkspaceSandbox(shell, options)
  } catch (err) {
    // A box the platform cannot bring up is not a transient failure: the box
    // key is derived from the workspace, so every later call resumes the same
    // dead box and fails the same way. Left alone the workspace never runs
    // again. Replacing it is a delete, so it happens only where the shell has
    // declared the box rebuildable — and only once, so a replacement that dies
    // the same way surfaces the error instead of looping.
    if (!shell.replaceUnbringableBox) throw err
    if (options.forceNew) throw err
    if (!isUnbringableBoxError(err)) throw err
    return await provisionWorkspaceSandbox(shell, { ...options, forceNew: true })
  }
}

/**
 * True when the platform cannot bring this box up where it lives.
 *
 * Two shapes reach here. `SandboxRecoveryFailedError` is the substrate's own
 * verdict after it tried a state-preserving restart and failed. A host-capacity
 * rejection is the same verdict one layer earlier: a box is pinned to a host,
 * and a full host rejects every resume for every box on it until something else
 * there goes away. Neither is transient, and neither is fixed by trying again
 * at the same key.
 */
function isUnbringableBoxError(error: unknown): boolean {
  if (error instanceof SandboxRecoveryFailedError) return true
  const diagnostics = serializeSandboxProvisioningError(error)
  return isSandboxHostCapacityFailure(diagnostics) || isSandboxBoxConfigFailure(diagnostics)
}

async function requestSandboxReplacement<TFailure extends StoppedSandboxResumeFailure>(
  recover: ((failure: TFailure) => Promise<Outcome<StoppedSandboxResumeRecovery | null>>) | undefined,
  failure: TFailure,
  label: string,
): Promise<StoppedSandboxResumeRecovery> {
  if (!recover) throw failure.error
  const recovery = await recover(failure)
  if (!recovery.succeeded) throw recovery.error
  if (!recovery.value) throw failure.error

  const replacementBoxKey = recovery.value.replacementBoxKey.trim()
  if (!replacementBoxKey || replacementBoxKey === failure.boxKey) {
    throw new Error(
      `${label} must return a fresh replacement box key for ${failure.boxKey}`,
      { cause: failure.error },
    )
  }
  return { ...recovery.value, replacementBoxKey }
}

async function requestMissingSandboxReplacement(
  shell: SandboxRuntimeConfig,
  failure: MissingSandboxFailure,
): Promise<StoppedSandboxResumeRecovery> {
  // Probe causes diagnose failed liveness; they do not authorize replacement.
  if (failure.error instanceof SandboxRecoveryFailedError && failure.error.phase === 'probe') {
    throw failure.error
  }
  const diagnostics = serializeSandboxProvisioningError(failure.error)
  if (!isSandboxApiSandboxMissingFailure(diagnostics)) throw failure.error
  return requestSandboxReplacement(
    shell.recoverMissingSandbox,
    failure,
    'missing sandbox recovery',
  )
}

async function provisionWorkspaceSandbox(
  shell: SandboxRuntimeConfig,
  options: EnsureWorkspaceSandboxOptions,
): Promise<SandboxInstance> {
  const execTimeoutMs = shell.livenessProbe?.execTimeoutMs
  // Match the supported SDK command-timeout range before any lifecycle mutation.
  if (execTimeoutMs !== undefined && (
    !Number.isInteger(execTimeoutMs) || execTimeoutMs < 100 || execTimeoutMs > 600_000
  )) {
    throw new Error('livenessProbe.execTimeoutMs must be an integer between 100 and 600000')
  }
  const { workspaceId, userId, harness, forceNew, onProgress, billingOwnerId } = options
  const resolved = await resolveWorkspaceSandboxClient(shell, workspaceId, userId)
  const { scope, client } = resolved
  let name = resolved.name
  let recoveryRestore: SandboxRestoreSpec | null | undefined
  let replacementRequested = false
  const resources = shell.resources ?? DEFAULT_SANDBOX_RESOURCES
  const resumeTimeout = shell.provisionTimeoutMs ?? DEFAULT_PROVISION_TIMEOUT_MS

  // Stage 1 — running-box reuse (skipped on forceNew).
  let existing = await listRunning(client, name)
  if (forceNew && existing.succeeded && !existing.value) {
    existing = await listStopped(client, name)
  }
  if (forceNew && !existing.succeeded) throw existing.error
  if (existing.succeeded && existing.value) {
    const found = existing.value
    if (forceNew) {
      const dropped = await deleteBox(found)
      if (!dropped.succeeded) {
        throw new Error(`forceNew: sandbox ${name} could not be deleted`, { cause: dropped.error })
      }
    } else if (found.metadata?.harness === harness) {
      try {
        const ready = await refreshRuntimeConnection(client, found)
        if ((await isReusableBox(ready, shell.livenessProbe)).succeeded) {
          return await finalizeExistingBox(shell, client, ready, 'reused', name, workspaceId, userId, harness, scope)
        }
        // Unresponsive (or never-connectable) box with the RIGHT harness: recover
        // in place — stop→resume preserves the workspace — and fail loud if the
        // box is still dead. Deleting here wiped user workspaces (#299); delete
        // is reachable only via forceNew now.
        const recovered = await recoverUnresponsiveBox(
          client,
          ready,
          shell.livenessProbe,
          'reused',
          name,
          resumeTimeout,
          onProgress,
        )
        return await finalizeExistingBox(shell, client, recovered, 'reused', name, workspaceId, userId, harness, scope)
      } catch (cause) {
        const error = cause instanceof Error ? cause : new Error(String(cause))
        const recovery = await requestMissingSandboxReplacement(shell, {
          box: found,
          error,
          scope,
          boxKey: name,
          stage: 'reused',
        })
        name = recovery.replacementBoxKey
        recoveryRestore = recovery.restore
        replacementRequested = true
      }
    } else {
      const dropped = await deleteBox(found)
      if (!dropped.succeeded) {
        throw new Error(
          `sandbox ${name} ` +
            `(was ${String(found.metadata?.harness ?? 'unknown')}, want ${harness}) ` +
            `could not be deleted`,
          { cause: dropped.error },
        )
      }
    }
  }

  // Stage 2 — stopped-box resume (skipped on forceNew or resumeStopped===false).
  if (!replacementRequested && !forceNew && shell.resumeStopped !== false) {
    const stopped = await listStopped(client, name)
    if (!stopped.succeeded) throw stopped.error
    if (stopped.value) {
      const resumed = await resumeStoppedBox(stopped.value, resumeTimeout, onProgress)
      if (!resumed.succeeded) {
        const recovery = await requestSandboxReplacement(
          shell.recoverStoppedSandbox,
          { box: stopped.value, error: resumed.error, scope, boxKey: name },
          'stopped sandbox recovery',
        )
        name = recovery.replacementBoxKey
        recoveryRestore = recovery.restore
      } else {
        try {
          const box = await refreshRuntimeConnection(client, resumed.value)
          if ((await isReusableBox(box, shell.livenessProbe)).succeeded) {
            return await finalizeExistingBox(shell, client, box, 'resumed', name, workspaceId, userId, harness, scope)
          }
          // The box resumed but is unresponsive: one full stop→resume cycle is
          // the state-preserving recovery; still-dead fails loud. Never delete —
          // that wipes the workspace (#299).
          const recovered = await recoverUnresponsiveBox(
            client,
            box,
            shell.livenessProbe,
            'resumed',
            name,
            resumeTimeout,
            onProgress,
          )
          return await finalizeExistingBox(shell, client, recovered, 'resumed', name, workspaceId, userId, harness, scope)
        } catch (cause) {
          const error = cause instanceof Error ? cause : new Error(String(cause))
          const recovery = await requestMissingSandboxReplacement(shell, {
            box: stopped.value,
            error,
            scope,
            boxKey: name,
            stage: 'resumed',
          })
          name = recovery.replacementBoxKey
          recoveryRestore = recovery.restore
        }
      }
    }
  }

  // Stage 3 — create fresh.
  const connectedIntegrationIds = await shell.connectedIntegrationIds(workspaceId)
  const buildCtx: SandboxBuildContext = {
    workspaceId,
    connectedIntegrationIds,
    ...(userId ? { userId } : {}),
  }
  const [secrets, creationEnv, runtimeEnv, files] = await Promise.all([
    shell.secrets(workspaceId),
    shell.env(buildCtx),
    resolveWorkspaceRuntimeEnv(shell, scope),
    shell.files(buildCtx),
  ])
  const env = { ...creationEnv, ...runtimeEnv }
  const fullProfile = shell.profile({ extraFiles: files, harness })
  // When deferring, strip inline files from the create payload and write them
  // into the box after it reaches running. Keeps the provision body under the
  // orchestrator's 256 KiB cap and lands real files on disk.
  const { leanProfile, deferredFiles } = shell.deferProfileFiles
    ? splitDeferredProfileFiles(fullProfile)
    : { leanProfile: fullProfile, deferredFiles: [] as AgentProfileFileMount[] }
  const profile = leanProfile

  const role = userId && shell.permissionRole ? shell.permissionRole('developer') : undefined

  // Bake the model at create when opted in. childKeyMint overrides the apiKey
  // per-workspace; a typed mint failure falls through to the parent key (logged).
  let model = shell.backendModelAtCreate
    ? requireTransportableModel(resolveModelSelection(shell.provider), `backendModelAtCreate for ${name}`)
    : undefined
  if (model && shell.childKeyMint && model.provider === 'openai-compat') {
    const minted = await shell.childKeyMint(scope)
    if (minted.succeeded) model = { ...model, apiKey: minted.value }
    else {
      console.error(
        `[sandbox] childKeyMint failed for ${workspaceId}; using parent key:`,
        minted.error.message,
      )
    }
  }

  const storage = shell.storage?.(buildCtx)
  const restore = recoveryRestore === undefined ? shell.restore?.(buildCtx) : recoveryRestore

  const payload = {
    name,
    image: resources.image,
    // Stamp the deferred-corpus hash so a later REUSE can skip re-writing an
    // unchanged skill corpus (materializeDeferredFilesForExistingBox reads it).
    metadata: {
      ...shell.metadata(harness),
      ...(deferredFiles.length > 0 ? { [DEFERRED_CORPUS_HASH_KEY]: deferredCorpusHash(deferredFiles) } : {}),
    },
    idempotencyKey: name,
    // Passed through untyped (the SDK payload type predates it); the platform
    // authz-gates it server-side and ignores it when unsupported.
    ...(billingOwnerId ? { billingOwnerId } : {}),
    ...(userId ? { permissions: { initialUsers: [{ userId, role }] } } : {}),
    env,
    secrets,
    backend: { type: harness, profile, ...(model ? { model } : {}) },
    ...(storage ? { storage } : {}),
    ...(restore ? restore : {}),
    ...(shell.egressPolicy ? { egressPolicy: shell.egressPolicy } : {}),
    ...(shell.cwd !== undefined ? { cwd: shell.cwd } : {}),
    ...(shell.webTerminalEnabled ? { webTerminalEnabled: true } : {}),
    maxLifetimeSeconds: resources.maxLifetimeSeconds,
    idleTimeoutSeconds: resources.idleTimeoutSeconds,
    resources: {
      cpuCores: resources.cpuCores,
      memoryMB: resources.memoryMB,
      diskGB: resources.diskGB,
    },
  } as CreatePayload

  // S-cost gates: an oversized env entry (E2BIG class), an over-cap provision
  // body, or a system prompt past the degradation cliff — fail loud here,
  // before the POST, with the offending section named. The prompt gate is
  // separate from the payload gate on purpose: the 122,659-byte prompt that
  // produced empty answers is a THIRD of the 240 KB payload cap, so the
  // payload gate never sees it.
  assertEnvWithinLimits(env)
  assertProfilePromptWithinBudget(
    profile,
    shell.promptBudget ?? {},
    `provision profile systemPrompt for ${name}`,
    SHELL_PROMPT_BUDGET_HINT,
  )
  // `?? {}` only narrows the SDK parameter's `| undefined`; the literal above
  // is always defined. The structural sections type needs no cast.
  assertProvisionPayloadWithinCap(payload ?? {})

  let box = await client.create(payload)

  await box.waitFor('running', {
    timeoutMs: shell.provisionTimeoutMs ?? DEFAULT_PROVISION_TIMEOUT_MS,
    ...(onProgress ? { onProgress } : {}),
  })
  box = await refreshRuntimeConnection(client, box)

  if (deferredFiles.length > 0) {
    const written = await writeProfileFilesToBox(box, deferredFiles)
    if (!written.succeeded) {
      throw deferredProfileWriteFailed('new', name, written.error)
    }
  }

  if (shell.bootstrap) {
    const boot = await shell.bootstrap(box, scope)
    if (!boot.succeeded) {
      throw new Error(`bootstrap failed on new box ${name}`, { cause: boot.error })
    }
  }
  return box
}

// The SDK's SandboxInstance.streamPrompt/.prompt accept `string | PromptInputPart[]`
// but the published package does not re-export the PromptInputPart type by name from
// any of its entry points, so it's derived structurally off the method signature
// itself — this stays in lockstep with the SDK's actual accepted shape.
/** Extract a single element type from the array parameter of SandboxInstance's streamPrompt method */
export type PromptInputPart = Extract<
  Parameters<SandboxInstance['streamPrompt']>[0],
  readonly unknown[]
>[number]

function historyTranscript(
  history: Array<{ role: 'user' | 'assistant'; content: string }>,
): string {
  return history
    .map((entry) => `${entry.role === 'assistant' ? 'Assistant' : 'User'}: ${entry.content}`)
    .join('\n\n')
}

/** Build a single string combining conversation history and the current user message */
export function flattenHistory(
  message: string,
  history?: Array<{ role: 'user' | 'assistant'; content: string }>,
): string {
  if (!history?.length) return message
  return `${historyTranscript(history)}\n\nUser: ${message}`
}

/**
 * History-aware equivalent of flattenHistory for multimodal prompt parts: the
 * transcript is folded into the first text part (image/file parts carry no
 * text to prepend to) rather than replacing the message wholesale.
 */
export function mergeHistoryIntoParts(
  parts: PromptInputPart[],
  history?: Array<{ role: 'user' | 'assistant'; content: string }>,
): PromptInputPart[] {
  if (!history?.length) return parts
  const textIndex = parts.findIndex((part) => part.type === 'text')
  if (textIndex === -1) {
    throw new Error('mergeHistoryIntoParts requires at least one text part to carry the history')
  }
  const textPart = parts[textIndex] as Extract<PromptInputPart, { type: 'text' }>
  const merged = [...parts]
  merged[textIndex] = { ...textPart, text: `${historyTranscript(history)}\n\nUser: ${textPart.text}` }
  return merged
}

/** Resolve conflicts and merge extra MCP profiles into the app tool MCP without overwriting existing keys */
export function mergeExtraMcp(
  appToolMcp: Record<string, AgentProfileMcpServer>,
  baseProfileMcp: Record<string, AgentProfileMcpServer>,
  extra: Record<string, AgentProfileMcpServer> | undefined,
): Record<string, AgentProfileMcpServer> {
  for (const key of Object.keys(extra ?? {})) {
    if (key in appToolMcp || key in baseProfileMcp) {
      throw new Error(`extraMcp key '${key}' collides with an existing profile MCP server`)
    }
  }
  return { ...appToolMcp, ...(extra ?? {}) }
}

/** Attach explicit effort through the portable model contract consumed by providers. */
export function attachReasoningEffort(
  profile: AgentProfile,
  _harness: Harness,
  effort: 'auto' | ReasoningEffort | undefined,
): AgentProfile {
  if (!effort || effort === 'auto') return profile
  return {
    ...profile,
    model: {
      ...profile.model,
      reasoningEffort: effort,
    },
  }
}

export interface SandboxPromptTokenLimits {
  maxVisibleOutputTokens?: number
  maxReasoningTokens?: number
  maxTotalOutputTokens?: number
}

function positiveSafeInteger(value: number | undefined, field: string): number | undefined {
  if (value === undefined) return undefined
  if (!Number.isSafeInteger(value) || value <= 0) {
    throw new Error(`${field} must be a positive safe integer`)
  }
  return value
}

function lowerCeiling(current: number | undefined, requested: number | undefined): number | undefined {
  if (current === undefined) return requested
  if (requested === undefined) return current
  return Math.min(current, requested)
}

/** Tighten the profile's provider-enforced token ceilings for one prompt. */
export function applyPromptTokenLimits(
  profile: AgentProfile,
  limits: SandboxPromptTokenLimits,
): AgentProfile {
  const requestedVisible = positiveSafeInteger(
    limits.maxVisibleOutputTokens,
    'maxVisibleOutputTokens',
  )
  const requestedReasoning = positiveSafeInteger(
    limits.maxReasoningTokens,
    'maxReasoningTokens',
  )
  const requestedTotal = positiveSafeInteger(
    limits.maxTotalOutputTokens,
    'maxTotalOutputTokens',
  )
  if (
    requestedVisible === undefined
    && requestedReasoning === undefined
    && requestedTotal === undefined
  ) return profile

  const maxTotalOutputTokens = lowerCeiling(
    profile.model?.maxTotalOutputTokens,
    requestedTotal,
  )
  let maxVisibleOutputTokens = lowerCeiling(
    profile.model?.maxVisibleOutputTokens,
    requestedVisible,
  )
  let maxReasoningTokens = lowerCeiling(
    profile.model?.maxReasoningTokens,
    requestedReasoning,
  )
  if (maxTotalOutputTokens !== undefined) {
    if (maxVisibleOutputTokens !== undefined) {
      maxVisibleOutputTokens = Math.min(maxVisibleOutputTokens, maxTotalOutputTokens)
    }
    if (maxReasoningTokens !== undefined) {
      maxReasoningTokens = Math.min(maxReasoningTokens, maxTotalOutputTokens)
    }
  }

  return {
    ...profile,
    model: {
      ...(profile.model ?? {}),
      ...(maxVisibleOutputTokens !== undefined ? { maxVisibleOutputTokens } : {}),
      ...(maxReasoningTokens !== undefined ? { maxReasoningTokens } : {}),
      ...(maxTotalOutputTokens !== undefined ? { maxTotalOutputTokens } : {}),
    },
  }
}

/** Define options for configuring and controlling a streaming sandbox prompt session */
export interface StreamSandboxPromptOptions {
  /** Complete server-owned profile for this turn. Skips the shell's default composer.
   * Credentials, admission, session identity, and interactions remain execution options.
   * Explicit turn selections override this profile; otherwise its model and harness win
   * over shell defaults. Never populate this field from an untrusted request body. */
  profile?: AgentProfile
  sessionId?: string
  executionId?: string
  /** Stable idempotency key for one logical dispatch. Reuse it with the same
   * `sessionId` when a caller may retry the initial request. */
  turnId?: string
  lastEventId?: string
  systemPrompt?: string
  model?: string
  modelApiKey?: string
  history?: Array<{ role: 'user' | 'assistant'; content: string }>
  harness?: Harness
  effort?: 'auto' | ReasoningEffort
  /** Provider-enforced visible answer ceiling for this turn. */
  maxOutputTokens?: number
  /** Provider-enforced hidden reasoning ceiling for this turn. */
  maxReasoningTokens?: number
  /** Provider-enforced combined answer and reasoning ceiling for this turn. */
  maxTotalOutputTokens?: number
  appToolMcp?: Record<string, AgentProfileMcpServer>
  baseProfileMcp?: Record<string, AgentProfileMcpServer>
  extraMcp?: Record<string, AgentProfileMcpServer>
  signal?: AbortSignal
  timeoutMs?: number
  requireVisibleAssistantOutput?: boolean
  // When true, an interactive question event throws instead of yielding.
  // Use this for detached runs whose caller has no consumer to answer it.
  disallowQuestions?: boolean
  // Per-turn question/permission/plan channel toggles, forwarded VERBATIM into the
  // backend config. agent-app does not validate kinds per harness — the sidecar fails
  // session init loudly for unsupported ones; a local matrix would drift. Honored on
  // both streaming and driveTurn paths.
  interactions?: { question?: boolean; permission?: boolean; plan?: boolean }
  // Streaming helper only: detach the run from THIS stream's lifetime. When true, the helper admits the
  // run through `dispatchPrompt`, then reads its exact execution through the
  // SDK replay stream. A Worker restart or browser refresh therefore cannot
  // cancel the server-side run. Reuse `sessionId` + `executionId` + `turnId` on
  // retries; `lastEventId` resumes the same execution instead of dispatching
  // another one.
  // Omit for a run where closing the tab should stop burning tokens.
  detach?: boolean
  // Observe the EXACT profile handed to the sandbox SDK for this turn — after
  // the system-prompt override, the MCP merge, and reasoning-effort attachment
  // — as a ProfileFingerprint. This is the seam an eval/backtest uses to PROVE
  // it executed the shipped profile instead of re-deriving one and asserting
  // nothing. Invoked once, before the first event is yielded.
  onProfileResolved?: (fingerprint: ProfileFingerprint) => void
  // Optional spend-verification activity tap. Omitted, nothing changes. Takes
  // the SAME object `ensureWorkspaceSandbox` does, so a product builds one and
  // wires it in both places; only `onActivity` is read here.
  spend?: SandboxSpendHooks
}

type StreamPromptOptions = Parameters<SandboxInstance['streamPrompt']>[1]
type DispatchPromptOptions = Parameters<SandboxInstance['dispatchPrompt']>[1]
type CompletedTurn = NonNullable<Awaited<ReturnType<SandboxInstance['findCompletedTurn']>>>

function cachedSandboxPromptEvents(
  cached: CompletedTurn,
  fallbackExecutionId: string,
): Array<Record<string, unknown>> {
  const cachedResult = cached.result
  const executionId = typeof cachedResult.executionId === 'string' && cachedResult.executionId.trim()
    ? cachedResult.executionId
    : fallbackExecutionId
  const finalText = typeof cachedResult.finalText === 'string'
    ? cachedResult.finalText
    : typeof cachedResult.response === 'string'
      ? cachedResult.response
      : typeof cachedResult.text === 'string'
        ? cachedResult.text
        : undefined

  return [
    {
      type: 'result',
      data: {
        ...cachedResult,
        ...(finalText !== undefined && cachedResult.finalText === undefined ? { finalText } : {}),
        sessionId: cached.sessionId,
        executionId,
      },
    },
    {
      type: 'done',
      data: {
        sessionId: cached.sessionId,
        executionId,
        status: 'completed',
        outcome: { type: 'completed' },
      },
    },
  ]
}

/**
 * Open the durable event lane for one detached prompt.
 *
 * `dispatchPrompt` is the admission boundary: it returns after the sandbox has
 * accepted the run and keeps executing it after this Worker disappears. The
 * SDK's execution replay stream is then the exact execution-scoped surface.
 * Replaying through `streamPrompt` preserves the direct run-event vocabulary;
 * the session bus wraps message parts under `data.properties`.
 */
async function* detachedSandboxPromptEvents(
  box: SandboxInstance,
  prompt: string | PromptInputPart[],
  options: StreamSandboxPromptOptions,
  backend: NonNullable<StreamPromptOptions>['backend'],
): AsyncGenerator<unknown> {
  const sessionId = options.sessionId?.trim()
  const executionId = options.executionId?.trim()
  if (!sessionId || !executionId) {
    throw new Error('streamSandboxPrompt detach requires stable sessionId and executionId')
  }

  const lastEventId = options.lastEventId?.trim() || undefined
  const turnId = options.turnId?.trim() || executionId
  // A cursor is already proof that this execution was admitted. Re-dispatching
  // before replay would turn a failed terminal session into a new prompt.
  const admission = lastEventId
    ? null
    : await box.dispatchPrompt(prompt, {
        sessionId,
        executionId,
        turnId,
        backend,
        ...(options.requireVisibleAssistantOutput !== undefined
          ? { requireVisibleAssistantOutput: options.requireVisibleAssistantOutput }
          : {}),
        ...(options.timeoutMs !== undefined ? { timeoutMs: options.timeoutMs } : {}),
      } as DispatchPromptOptions)
  const admittedExecutionId = admission?.executionId ?? executionId
  if (!admittedExecutionId) {
    throw new Error(`detached Sandbox dispatch for ${sessionId} returned no executionId`)
  }

  // A completed-turn cache hit deliberately returns `dispatched: false` and
  // emits no new stream events. Yield its public result directly; the replay
  // buffer may already have aged out by the time a retry reaches this helper.
  if (admission?.dispatched === false) {
    const cached = await box.findCompletedTurn(turnId, { sessionId })
    if (cached) {
      yield* cachedSandboxPromptEvents(cached, admittedExecutionId)
      return
    }
  }

  // The session bus is a useful observation surface, but its message events
  // use a different envelope (`data.properties.part`). Use the SDK's exact
  // execution replay instead so downstream producers receive the same event
  // vocabulary as a direct prompt stream (`data.part`, terminal `result`, etc.).
  yield* box.streamPrompt('', {
    sessionId: admission?.sessionId ?? sessionId,
    executionId: admittedExecutionId,
    lastEventId: lastEventId || '0',
    ...(options.signal ? { signal: options.signal } : {}),
  } as StreamPromptOptions)
}

/**
 * The small event shape consumed by agent-gateway's streaming adapters.
 *
 * Sandbox providers can add fields to their event payloads over time. This
 * adapter deliberately copies only the fields the gateway understands so
 * consumers do not each have to maintain a provider-to-gateway cast.
 */
export interface SandboxStreamEvent {
  type?: string
  data?: {
    part?: { type?: string; text?: string }
    delta?: string
    finalText?: string
    code?: string
    message?: string
    details?: Record<string, unknown>
    inputRequired?: { prompt?: string }
    usage?: {
      inputTokens?: number
      outputTokens?: number
      reasoningTokens?: number
      toolTokens?: number
      toolCallCount?: number
      providerCostUsd?: number
      budgetEnforced?: boolean
    }
    tool?: { name?: string; inputTokens?: number; outputTokens?: number }
    reasoning?: { tokens?: number }
  }
}

function optionalNonNegativeNumber(
  value: unknown,
  field: string,
): number | undefined {
  if (value === undefined) return undefined
  if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
    throw new Error(`sandbox gateway event ${field} is invalid`)
  }
  return value
}

function optionalNonNegativeSafeInteger(
  value: unknown,
  field: string,
): number | undefined {
  const number = optionalNonNegativeNumber(value, field)
  if (number !== undefined && !Number.isSafeInteger(number)) {
    throw new Error(`sandbox gateway event ${field} is invalid`)
  }
  return number
}

function optionalGatewayRecord(
  value: unknown,
  field: string,
): Record<string, unknown> | undefined {
  if (value === undefined) return undefined
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`sandbox gateway event ${field} is invalid`)
  }
  return value as Record<string, unknown>
}

/** Normalize raw sandbox events for shared agent-gateway consumers. */
export function adaptSandboxStream(
  events: AsyncIterable<unknown>,
): AsyncGenerator<SandboxStreamEvent> {
  return (async function* () {
    for await (const rawEvent of events) {
      if (!rawEvent || typeof rawEvent !== 'object' || Array.isArray(rawEvent)) continue

      const event = rawEvent as Record<string, unknown>
      const rawData = event.data
      const dataRecord =
        rawData && typeof rawData === 'object' && !Array.isArray(rawData)
          ? (rawData as Record<string, unknown>)
          : null
      const data: NonNullable<SandboxStreamEvent['data']> = {}

      const rawPart = dataRecord?.part
      if (rawPart && typeof rawPart === 'object' && !Array.isArray(rawPart)) {
        const part = rawPart as Record<string, unknown>
        const normalizedPart: NonNullable<
          NonNullable<SandboxStreamEvent['data']>['part']
        > = {}
        if (typeof part.type === 'string') normalizedPart.type = part.type
        if (typeof part.text === 'string') normalizedPart.text = part.text
        if (Object.keys(normalizedPart).length > 0) data.part = normalizedPart
      }

      if (typeof dataRecord?.delta === 'string') data.delta = dataRecord.delta
      if (typeof dataRecord?.finalText === 'string') data.finalText = dataRecord.finalText
      if (typeof dataRecord?.code === 'string') data.code = dataRecord.code
      if (typeof dataRecord?.message === 'string') data.message = dataRecord.message
      const rawDetails = dataRecord?.details
      if (rawDetails && typeof rawDetails === 'object' && !Array.isArray(rawDetails)) {
        data.details = rawDetails as Record<string, unknown>
      }

      const usageRecord = optionalGatewayRecord(dataRecord?.usage, 'usage')
      if (usageRecord) {
        const usage: NonNullable<NonNullable<SandboxStreamEvent['data']>['usage']> = {}
        for (const field of [
          'inputTokens',
          'outputTokens',
          'reasoningTokens',
          'toolTokens',
          'toolCallCount',
        ] as const) {
          const value = optionalNonNegativeSafeInteger(usageRecord[field], `usage.${field}`)
          if (value !== undefined) usage[field] = value
        }
        const providerCostUsd = optionalNonNegativeNumber(
          usageRecord.providerCostUsd,
          'usage.providerCostUsd',
        )
        if (providerCostUsd !== undefined) usage.providerCostUsd = providerCostUsd
        if (usageRecord.budgetEnforced !== undefined) {
          if (typeof usageRecord.budgetEnforced !== 'boolean') {
            throw new Error('sandbox gateway event usage.budgetEnforced is invalid')
          }
          usage.budgetEnforced = usageRecord.budgetEnforced
        }
        if (Object.keys(usage).length > 0) data.usage = usage
      }

      const toolRecord = optionalGatewayRecord(dataRecord?.tool, 'tool')
      if (toolRecord) {
        const tool: NonNullable<NonNullable<SandboxStreamEvent['data']>['tool']> = {}
        if (typeof toolRecord.name === 'string') tool.name = toolRecord.name
        const inputTokens = optionalNonNegativeSafeInteger(toolRecord.inputTokens, 'tool.inputTokens')
        const outputTokens = optionalNonNegativeSafeInteger(toolRecord.outputTokens, 'tool.outputTokens')
        if (inputTokens !== undefined) tool.inputTokens = inputTokens
        if (outputTokens !== undefined) tool.outputTokens = outputTokens
        if (Object.keys(tool).length > 0) data.tool = tool
      }

      const reasoningRecord = optionalGatewayRecord(dataRecord?.reasoning, 'reasoning')
      if (reasoningRecord) {
        const tokens = optionalNonNegativeSafeInteger(
          reasoningRecord.tokens,
          'reasoning.tokens',
        )
        if (tokens !== undefined) data.reasoning = { tokens }
      }

      const rawInputRequired = dataRecord?.inputRequired
      if (
        rawInputRequired &&
        typeof rawInputRequired === 'object' &&
        !Array.isArray(rawInputRequired)
      ) {
        const prompt = (rawInputRequired as Record<string, unknown>).prompt
        data.inputRequired = typeof prompt === 'string' ? { prompt } : {}
      }

      yield {
        ...(typeof event.type === 'string' ? { type: event.type } : {}),
        ...(Object.keys(data).length > 0 ? { data } : {}),
      }
    }
  })()
}

/** Configuration needed to prepare a turn without provisioning a workspace. */
export type SandboxPromptConfig = Pick<SandboxRuntimeConfig, 'provider' | 'deferProfileFiles' | 'promptBudget'>
  & Partial<Pick<SandboxRuntimeConfig, 'profile'>>

/** Prepare one effective backend for SDK dispatch or product-specific transport.
 * Supply a server-owned profile, or a shell composer for the default profile.
 * Reuse the returned backend for preflight and dispatch so they inspect identical configuration.
 */
export async function resolveSandboxPromptBackend(
  shell: SandboxPromptConfig,
  options: StreamSandboxPromptOptions,
  operation = 'sandbox prompt',
) {
  const initialHarness = options.harness ?? options.profile?.harness ?? DEFAULT_HARNESS
  if (!isHarness(initialHarness)) throw new Error(`Unsupported sandbox harness: ${initialHarness}`)
  const extraMcp = mergeExtraMcp(
    options.appToolMcp ?? {},
    options.profile?.mcp ?? options.baseProfileMcp ?? {},
    options.extraMcp,
  )
  const compose = (harness: Harness) => {
    if (!shell.profile) throw new Error(`${operation}: supply a profile or a shell profile composer`)
    return shell.profile({ systemPrompt: options.systemPrompt, extraMcp, harness })
  }
  let fullProfile = options.profile
    ? mergeAgentProfiles(options.profile, {
        ...(options.systemPrompt !== undefined ? { prompt: { systemPrompt: options.systemPrompt } } : {}),
        ...(Object.keys(extraMcp).length > 0 ? { mcp: extraMcp } : {}),
      })!
    : compose(initialHarness)
  const harness = options.harness ?? fullProfile.harness ?? DEFAULT_HARNESS
  if (!isHarness(harness)) throw new Error(`Unsupported sandbox harness: ${harness}`)
  // Older composers may place harness-native files. Recompose if their authored
  // preference differs from the default used to discover that preference.
  if (!options.profile && harness !== initialHarness) fullProfile = compose(harness)

  const explicitModel = trimOrNull(options.model)
  const profileModel = trimOrNull(fullProfile.model?.default)
  const profileProvider = profileModel && (!explicitModel || explicitModel === profileModel)
    ? trimOrNull(fullProfile.model?.provider)
    : null
  const model = requireTransportableModel(
    resolveModelSelection({
      ...shell.provider,
      providerName: trimOrNull(shell.provider?.providerName) ?? profileProvider ?? undefined,
    }, {
      model: explicitModel ?? profileModel ?? undefined,
      modelApiKey: options.modelApiKey,
    }),
    operation,
  )
  // Profile provider evidence belongs only to its own selected model; the
  // transport provider may instead identify a router serving that vendor.
  if (model) assertHarnessModelCompatible(harness, {
    ...model,
    provider: profileProvider ?? model.provider,
  })

  const selectedProfile: AgentProfile = {
    ...fullProfile,
    harness,
    // The materializer compares the profile and transport as provider-qualified
    // identities. Authored provider evidence has already served preflight above.
    ...(model ? { model: { ...fullProfile.model, provider: model.provider, default: model.model } } : {}),
  }
  // The deferred writer owns shell-composed files only. Supplied profiles
  // must retain their resources for the SDK to materialize this turn.
  const executionProfile = shell.deferProfileFiles && !options.profile
    ? splitDeferredProfileFiles(selectedProfile).leanProfile
    : selectedProfile
  const profile = applyPromptTokenLimits(
    attachReasoningEffort(executionProfile, harness, options.effort),
    {
      maxVisibleOutputTokens: options.maxOutputTokens,
      maxReasoningTokens: options.maxReasoningTokens,
      maxTotalOutputTokens: options.maxTotalOutputTokens,
    },
  )
  assertProfilePromptWithinBudget(
    profile, shell.promptBudget ?? {}, `${operation} profile systemPrompt`, SHELL_PROMPT_BUDGET_HINT,
  )
  if (options.onProfileResolved) {
    options.onProfileResolved(await fingerprintAgentProfile(profile, { model: model?.model, harness }))
  }
  return {
    type: harness,
    profile,
    ...(model ? { model } : {}),
    ...(options.interactions ? { interactions: options.interactions } : {}),
  }
}

/** Resolve and stream AI-generated responses from a sandboxed environment based on input messages and options */
export async function* streamSandboxPrompt(
  shell: SandboxRuntimeConfig,
  box: SandboxInstance,
  message: string | PromptInputPart[],
  options?: StreamSandboxPromptOptions,
): AsyncGenerator<unknown> {
  const backend = await resolveSandboxPromptBackend(shell, options ?? {}, 'streamSandboxPrompt')
  const prompt =
    typeof message === 'string'
      ? flattenHistory(message, options?.history)
      : mergeHistoryIntoParts(message, options?.history)

  const stream = options?.detach
    ? detachedSandboxPromptEvents(box, prompt, options, backend)
    : box.streamPrompt(prompt, {
        sessionId: options?.sessionId,
        executionId: options?.executionId,
        turnId: options?.turnId,
        lastEventId: options?.lastEventId,
        ...(options?.signal ? { signal: options.signal } : {}),
        ...(options?.timeoutMs !== undefined ? { timeoutMs: options.timeoutMs } : {}),
        ...(options?.requireVisibleAssistantOutput !== undefined
          ? { requireVisibleAssistantOutput: options.requireVisibleAssistantOutput }
          : {}),
        backend,
      } as StreamPromptOptions)

  emitSandboxActivity(options?.spend, box)
  let severedFinishReason: string | null = null
  try {
    for await (const event of stream) {
      const step = classifySeveredStream(event)
      if (step) severedFinishReason = step.kind === 'step-finish' && step.severed ? step.reason : null
      if (severedFinishReason && isTerminalPromptEvent(event)) {
        throw new Error(`sandbox model stream severed mid-turn (reason="${severedFinishReason}")`)
      }
      if (options?.disallowQuestions) {
        const q = detectInteractiveQuestion(event)
        if (q) {
          throw new Error(`sandbox agent asked an interactive question during an autonomous run: ${q}`)
        }
      }
      yield event
    }
  } finally {
    // The box was working right up to here, however this turn ended — a throw,
    // an abandoned generator and a clean finish all bill the same.
    emitSandboxActivity(options?.spend, box)
  }
  // Reconnect-exhausted path: the stream ended on a severed step without a
  // terminal event. A truncated turn must fail loud, not return silently.
  if (severedFinishReason) {
    throw new Error(`sandbox model stream severed mid-turn (reason="${severedFinishReason}")`)
  }
}

/**
 * Stable identity for a streamed text part, so deltas of one part accumulate
 * together and two concurrent parts never overwrite each other. Harnesses spell
 * the id differently and some snapshot updates carry none at all.
 *
 * Deliberately NOT `/stream`'s `getPartKey`, despite the overlapping property
 * lookup: that one resolves a key for any persisted part across every type and
 * falls back to the CONSTANT `'current'`, which merges all id-less parts into a
 * single lane. Here an id-less part must stay distinct — merging two of them
 * would silently drop one candidate answer, the exact failure class this
 * function was changed to fix. Sharing three lines of lookup would also couple
 * `/sandbox` to `/stream`, which are independent subpaths today.
 */
function textPartId(part: Record<string, unknown> | undefined, fallback: string): string {
  for (const key of ['id', 'partId', 'messagePartId']) {
    const value = part?.[key]
    if (typeof value === 'string' && value.trim()) return value
  }
  return fallback
}

/**
 * The prompt text a harness may replay back as an assistant text part before it
 * answers. Both spellings are collected because `streamSandboxPrompt` dispatches
 * the HISTORY-FOLDED prompt, not the raw message — an echo replays what was sent.
 */
function dispatchedPromptTexts(
  message: string | PromptInputPart[],
  history: StreamSandboxPromptOptions['history'],
): string[] {
  const raw =
    typeof message === 'string'
      ? message
      : ((message.find((part) => part.type === 'text') as { text?: string } | undefined)?.text ?? '')
  return [...new Set([raw, flattenHistory(raw, history)].map((text) => text.trim()))].filter(Boolean)
}

/**
 * The last streamed text part that is not a replay of the prompt. Used only when
 * the turn carried no `result` receipt.
 *
 * Two distinct decisions, and only the first is content-based. WHICH parts are
 * eligible is decided by CONTENT — an echo is excluded because it matches the
 * dispatched prompt, at whatever position it arrived. Choosing among the
 * remaining eligible parts is then ordinal, last-wins, because a harness emits
 * reasoning/preamble parts before the answer. That ordering assumption is safe
 * in a way "skip the first part" was not: it can only pick the wrong part when a
 * turn produced several genuine non-echo texts and the final one is not the
 * answer, whereas the positional rule mis-fired on the single-answer case that
 * is overwhelmingly the common one.
 */
function lastNonPromptTextPart(parts: Map<string, string>, promptTexts: string[]): string {
  const values = Array.from(parts.values())
    .map((value) => value.trim())
    .filter((value) => value && !promptTexts.includes(value))
  return values.at(-1) ?? ''
}

/**
 * Aggregate a sandbox prompt event stream down to the turn's one final answer.
 *
 * Exported SEPARATELY from `runSandboxPrompt` because the aggregation is pure —
 * `AsyncIterable<event> -> string` — while the streaming half is not: a product
 * that mounts per-turn MCP servers or resolves its harness per workspace wraps
 * `streamSandboxPrompt` in its own generator. Binding this logic to one stream
 * function is exactly what pushed three products into forking the whole thing,
 * bug and all. Take this over a local copy no matter whose generator you drive.
 *
 * Two rules earn their keep, and both were learned from the naive version:
 *
 * - Text accumulates PER PART ID, never into one running buffer, so two
 *   concurrent text parts cannot overwrite each other.
 * - A prompt echo is identified by CONTENT, never by arrival position. The
 *   "skip whichever text part arrives first" shortcut is wrong on both sandbox
 *   lanes: on the delta lane (`box.streamPrompt`, explicit deltas) the first
 *   part is the answer's opening token, so the answer silently loses it; and
 *   when the echo arrives AFTER the answer, the function returns the caller's
 *   own prompt as the agent's reply. Both failures produce a plausible-looking
 *   string, the worst shape for the unattended cron/judge turns this exists for.
 *
 * A blank-but-present `result.finalText` is ignored in favour of the streamed
 * text rather than overwriting a real answer with whitespace.
 *
 * @param events raw sandbox turn events, in order
 * @param message the prompt as handed to the stream, so an echo of it is dropped
 * @param history folded into the dispatched prompt by `streamSandboxPrompt`;
 *        pass whatever was passed there, since the echo replays the FOLDED text
 */
export async function collectSandboxPromptText(
  events: AsyncIterable<unknown>,
  message: string | PromptInputPart[],
  history?: StreamSandboxPromptOptions['history'],
): Promise<string> {
  let finalText = ''
  const textParts = new Map<string, string>()
  let anonymousTextPart = 0

  for await (const rawEvent of events) {
    const event = rawEvent as { type?: string; data?: Record<string, unknown> }
    if (!event.type) continue

    if (event.type === 'message.part.updated') {
      const part = event.data?.part as Record<string, unknown> | undefined
      const delta = typeof event.data?.delta === 'string' ? event.data.delta : null
      if (String(part?.type ?? '') === 'text') {
        const partId = textPartId(part, delta ? 'delta' : `text-${anonymousTextPart++}`)
        if (delta) textParts.set(partId, `${textParts.get(partId) ?? ''}${delta}`)
        else if (typeof part?.text === 'string') textParts.set(partId, part.text)
      }
    } else if (event.type === 'result') {
      const resultText = typeof event.data?.finalText === 'string' ? event.data.finalText : null
      if (resultText?.trim()) finalText = resultText
    }
  }

  return finalText || lastNonPromptTextPart(textParts, dispatchedPromptTexts(message, history))
}

/**
 * Resolve a sandbox prompt by streaming it and aggregating the turn down to one
 * final string. The shell's profile / model / MCP resolution and severed-stream
 * fail-loud come from `streamSandboxPrompt`; the aggregation is
 * `collectSandboxPromptText`, which products driving their own generator should
 * import directly.
 */
export async function runSandboxPrompt(
  shell: SandboxRuntimeConfig,
  box: SandboxInstance,
  message: string | PromptInputPart[],
  options?: StreamSandboxPromptOptions,
): Promise<string> {
  return collectSandboxPromptText(
    streamSandboxPrompt(shell, box, message, options),
    message,
    options?.history,
  )
}

// Mirrors the SDK's PermissionLevel union (not re-exported by
// @tangle-network/sandbox). The product's role-mapping seam must produce one of
// these; binding the seam's return type to the union makes a wrong mapping a
// compile error rather than a runtime 400 from the orchestrator.
/** Define permission levels for sandbox access and control */
export type SandboxPermissionLevel = 'owner' | 'admin' | 'developer' | 'viewer'

/** Map workspace roles to corresponding sandbox permission levels */
export interface MemberSyncSeam {
  roleToSandboxRole: (workspaceRole: string) => SandboxPermissionLevel
}

/** Resolve adding a user with a specific role to a sandbox and return the operation outcome */
export async function syncSandboxMemberAdd(
  box: SandboxInstance,
  seam: MemberSyncSeam,
  userId: string,
  role: string,
): Promise<Outcome<void>> {
  try {
    await box.permissions.add({ userId, role: seam.roleToSandboxRole(role) })
    return ok(undefined)
  } catch (err) {
    return fail(err)
  }
}

/** Remove a member from the sandbox while preserving their home directory and handle the outcome */
export async function syncSandboxMemberRemove(
  box: SandboxInstance,
  userId: string,
): Promise<Outcome<void>> {
  try {
    await box.permissions.remove(userId, { preserveHomeDir: true })
    return ok(undefined)
  } catch (err) {
    return fail(err)
  }
}

/** Synchronize a sandbox member's role by updating permissions based on the provided role mapping */
export async function syncSandboxMemberRole(
  box: SandboxInstance,
  seam: MemberSyncSeam,
  userId: string,
  role: string,
): Promise<Outcome<void>> {
  try {
    await box.permissions.update(userId, { role: seam.roleToSandboxRole(role) })
    return ok(undefined)
  } catch (err) {
    return fail(err)
  }
}

/**
 * Write-only secret port: create, replace, and delete a secret by name.
 *
 * There is no read method. The platform's secrets API returns names and
 * timestamps only — a stored value is never served back, it is injected into
 * the sandbox as an environment variable. A `get` here could only ever return
 * a value this process already held, so the port does not offer one.
 */
export interface SecretStore {
  create: (name: string, value: string) => Promise<void>
  update: (name: string, value: string) => Promise<void>
  delete: (name: string) => Promise<void>
}

/** Resolve a SecretStore interface using the provided SandboxRuntimeConfig shell */
export function secretStoreFromClient(shell: SandboxRuntimeConfig): SecretStore {
  const client = getClient(shell)
  return {
    create: async (name, value) => {
      await client.secrets.create(name, value)
    },
    // The API has no replace route, so a replacement is a delete followed by a
    // create. That pair is NOT atomic: if the create fails, the secret is left
    // deleted rather than at its previous value. `storeSecret` reports that
    // state instead of reporting a generic write failure, because a caller
    // retrying a lost secret needs to know it is now absent.
    update: async (name, value) => {
      await client.secrets.delete(name)
      await client.secrets.create(name, value)
    },
    delete: async (name) => {
      await client.secrets.delete(name)
    },
  }
}

/** Resolve storing a secret by creating it, or replacing it when it exists */
export async function storeSecret(
  store: SecretStore,
  name: string,
  value: string,
): Promise<Outcome<void>> {
  try {
    await store.create(name, value)
    return ok(undefined)
  } catch {
    try {
      await store.update(name, value)
      return ok(undefined)
    } catch (err) {
      return fail(
        new Error(
          `Failed to store sandbox secret ${name}. A replacement deletes before it creates, so ${name} may now be absent rather than holding its previous value.`,
          { cause: err },
        ),
      )
    }
  }
}

/** Delete a secret by name from the given secret store and return the operation outcome */
export async function deleteSecret(store: SecretStore, name: string): Promise<Outcome<void>> {
  try {
    await store.delete(name)
    return ok(undefined)
  } catch (err) {
    return fail(err)
  }
}

/** Represent a token with its expiration date and associated scope */
export interface ScopedTokenResult {
  token: string
  expiresAt: Date
  scope: ScopedTokenScope
}

/**
 * Mint a scoped token for an already-provisioned box (e.g. to hand a terminal
 * proxy a narrowed credential). Uses the SDK's native `box.mintScopedToken`,
 * which normalizes `expiresAt` to a Date — no hand-rolled wire call.
 */
export async function mintSandboxScopedToken(
  box: SandboxInstance,
  options: MintScopedTokenOptions,
): Promise<Outcome<ScopedTokenResult>> {
  try {
    const token = await box.mintScopedToken(options)
    return ok({ token: token.token, expiresAt: token.expiresAt, scope: token.scope })
  } catch (err) {
    return fail(err)
  }
}

/** Define options to manage deterministic session resumption and turn idempotency in sandboxed drive turns */
export interface DriveSandboxTurnOptions extends StreamSandboxPromptOptions {
  /** Deterministic resume key — required. Every tick for the same logical turn
   * MUST reuse it so a crash + re-drive finds the in-flight session instead of
   * starting a second agent run. */
  sessionId: string
  /** Wall-clock cap in ms from the session's start. A still-running session past
   * the cap is cancelled and reported `failed` — bounds an unattended run, such as
   * a turn stalled on an interactive question with no consumer. Omit for no cap. */
  wallCapMs?: number
}

// One settle → poll → dispatch pass over a detached turn. Delegates to the SDK's
// `box.driveTurn` (@tangle-network/sandbox ≥ 0.10.5). Sandbox 0.37 admits the
// turn through the session message lane, so a SessionGateway consumer can observe it.
// The turn runs fire-and-detached server-side. ONE invocation returns its current
// state immediately. It never awaits the whole turn in-process, so it does not hold the
// worker alive for the run's duration (the durability trap the older box.prompt
// implementation quietly caused).
//
// This is the durable path for cron / mission-step / queue callers: re-invoke on
// your own schedule (Workflow step, DO alarm, queue tick) with the SAME
// `sessionId` and `turnId`. Dispatch is idempotent on that pair, so a crash +
// re-drive is a lookup, not a second agent run.
//
// The Outcome boundary separates a retryable transport failure from a settled
// turn: `fail` means the drive call itself threw (network blip — retry the tick);
// `ok` carries the SDK's discriminated `TurnDriveResult` — inspect `.state`:
//   - `running`   → the turn is still executing; re-tick after a delay of your choosing.
//   - `completed` → terminal; `.text` / `.result` hold the payload.
//   - `failed`    → terminal and deterministic; re-invoking will not change it (do not retry).
//   - `awaiting_plan_decision`, `blocked_on_approval`, `awaiting_question`,
//     `awaiting_interaction` → the turn settled waiting on a decision. Sandbox
//     0.45 reports the last three as `failed`.
/** Resolve a sandbox turn by processing a message with given configuration and options */
export async function driveSandboxTurn(
  shell: SandboxRuntimeConfig,
  box: SandboxInstance,
  message: string | PromptInputPart[],
  options: DriveSandboxTurnOptions,
): Promise<Outcome<TurnDriveResult>> {
  // Configuration failures precede the retryable transport boundary.
  const backend = await resolveSandboxPromptBackend(shell, options, 'driveSandboxTurn')
  const prompt =
    typeof message === 'string'
      ? flattenHistory(message, options.history)
      : mergeHistoryIntoParts(message, options.history)
  try {
    const drive = await box.driveTurn(prompt, {
      sessionId: options.sessionId,
      ...(options.turnId ? { turnId: options.turnId } : {}),
      ...(options.wallCapMs !== undefined ? { wallCapMs: options.wallCapMs } : {}),
      ...(options.timeoutMs !== undefined ? { timeoutMs: options.timeoutMs } : {}),
      ...(options.signal ? { signal: options.signal } : {}),
      // Sandbox 0.37 drives through the session message lane, so a gateway
      // consumer can handle these events. Callers without one should omit
      // interactions so the run stays unattended.
      backend,
    } as Parameters<SandboxInstance['driveTurn']>[1])
    // The autonomous lane needs this most: a detached turn keeps the box
    // billable with nobody watching, and every tick that reports `running` is
    // fresh evidence it is still working. Without it the expectation ceiling
    // rests on whenever the box was last provisioned.
    emitSandboxActivity(options.spend, box)
    return ok(drive)
  } catch (err) {
    return fail(err)
  }
}

// Severed-stream classifier. Generic to any router-backed harness: a final step
// that finished with error/other/unknown is a truncated turn, not a completed one.
const SEVERED_FINISH_REASONS = new Set(['error', 'other', 'unknown'])

/** Define transitions marking the start or finish of a sandbox step with associated details */
export type SandboxStepTransition =
  | { kind: 'step-start' }
  | { kind: 'step-finish'; reason: string; severed: boolean }

function asPlainRecord(v: unknown): Record<string, unknown> | null {
  return v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : null
}

/** Resolve the severed stream event to a corresponding sandbox step transition or null */
export function classifySeveredStream(event: unknown): SandboxStepTransition | null {
  const root = asPlainRecord(event)
  if (!root || root.type !== 'message.part.updated') return null
  const body = asPlainRecord(root.properties) ?? asPlainRecord(root.data) ?? root
  const part = asPlainRecord(body.part)
  if (!part) return null
  if (part.type === 'step-start') return { kind: 'step-start' }
  if (part.type !== 'step-finish') return null
  const reason = typeof part.reason === 'string' && part.reason ? part.reason : 'unknown'
  return { kind: 'step-finish', reason, severed: SEVERED_FINISH_REASONS.has(reason) }
}

/** Determine if an event is a terminal prompt event with type 'result' or 'done */
export function isTerminalPromptEvent(event: unknown): boolean {
  const t = asPlainRecord(event)?.type
  return t === 'result' || t === 'done'
}

// Interactive-question detector. Returns the question text or null. Used by
// streamSandboxPrompt when disallowQuestions is set.
/** Resolve the interactive question text from a structured event or return null if none found */
export function detectInteractiveQuestion(event: unknown): string | null {
  const root = asPlainRecord(event)
  if (!root) return null
  const type = typeof root.type === 'string' ? root.type : undefined
  const data = asPlainRecord(root.data)
  const props = asPlainRecord(root.properties)
  const body = props ?? data ?? root
  if (type === 'question.asked' || type === 'question') return firstQuestionText(body)
  // Generic structured-interaction event (BackendConfig.interactions kinds surface as
  // `interaction` events with a `kind` discriminator); treat kind:"question" as a question.
  if (type === 'interaction' && body.kind === 'question') return firstQuestionText(body)
  const part = asPlainRecord(data?.part) ?? asPlainRecord(body.part)
  const tool =
    (typeof part?.tool === 'string' && part.tool) ||
    (typeof part?.name === 'string' && part.name) ||
    (typeof body.tool === 'string' && body.tool) ||
    undefined
  const isQ =
    type === 'message.part.updated' &&
    (tool === 'question' || asPlainRecord(part)?.type === 'question')
  if (!isQ) return null
  const state = asPlainRecord(asPlainRecord(part)?.state)
  return firstQuestionText(asPlainRecord(state?.input) ?? state ?? part ?? body)
}

function firstQuestionText(value: Record<string, unknown> | null): string {
  const arr = Array.isArray(value?.questions)
    ? value!.questions
    : Array.isArray(asPlainRecord(value?.input)?.questions)
      ? (asPlainRecord(value!.input)!.questions as unknown[])
      : []
  const first = asPlainRecord(arr[0])
  const q =
    (typeof first?.question === 'string' && first.question) ||
    (typeof first?.prompt === 'string' && first.prompt) ||
    undefined
  return q ?? 'interactive question'
}
